import fs from 'node:fs';
const path='src/features/catalog/CatalogSearchResults.tsx';
let source=fs.readFileSync(path,'utf8');
const from='producerVerified: metric?.verified ?? true,';
const to='producerVerified: metric?.verified ?? false,';
const count=source.split(from).length-1;
if(count!==1)throw new Error(`Expected one unsafe producer verification fallback, found ${count}`);
source=source.replace(from,to);
fs.writeFileSync(path,source);
console.log('Catalog producer verification fallback now fails closed.');
